invalid.script:
(blockcontext, pageContext, item) => {
    return blockcontext.selectedRoles.length === 0;
//return blockcontext.var1 + blockcontext.var2
}

messages.script:
(blockcontext, pageContext, item) => {
    var showAlert = blockcontext.selectedRoles.length === 0;
    if (showAlert) {
        return [{
            "icon": "exclamation-triangle-outline",
            "status": "critical",
            "content": "At least 1 role must be selected for a skill. If you do not wish to define any role, you may select ‘Any authenticated user’."
        }];
    } else {
        return [{
            "icon": "circle-info-outline",
            "status": "info",
            "content": "Role changes will be saved and applied to the skill."
        }];
    }
//return blockcontext.var1 + blockcontext.var2
}
